+function pickBestServerLink($: any, p: any): PickedLink | null {
+  const candidates: PickedLink[] = [];
+  p.find("a").each((_: number, a: any) => {
+    const $a = $(a);
+    const href: string | undefined = $a.attr("href");
+    if (!href) return;
